 error(e){const t=this.t;return ({GATE_FINAL_APPROVAL_REQUIRED:t('必须完成最终出库审批后才能办理出厂','Final stock issue approval is required'),GATE_TEMPLATE_CHANGED:t('出门证模板已更新，请刷新后重试','The gate template changed. Refresh and retry.'),GATE_SOURCE_MISSING:t('业务资料不完整，请先核对原单的Lot/备货批次、车牌、司机、装箱单号、数量、重量及铜捆包片数；不能用样例填补','Source data is incomplete. Verify the Lot/preparation batch, plate, driver, packing list, quantity, weight and copper sheet counts. Sample data cannot be used'),GATE_STALE:t('记录已更新，请刷新核对后再提交','This record changed. Refresh and verify before submitting'),GATE_ALREADY_EXITED:t('车辆已经确认出厂，不能修改原出厂事实','Gate exit is already confirmed and cannot be edited'),GATE_PRINT_AND_ACTUAL_TIME_REQUIRED:t('请先打开当前版本打印窗口；实际出厂时间应介于本版生成时间和当前时间之间','Open the current print version first. Actual exit must be between its generation time and now'),GATE_SALES_REQUIRED:t('当前账号没有实际出厂确认权限','This account cannot confirm physical gate exit'),GATE_CONFLICT:t('状态、版本、打印记录或出厂时间不符，请刷新核对','State, version, print record or exit time does not match. Refresh and verify')}[e.message]||e.message);},
 page(title,html){Router.page(title,'<div class="gate-page shipping-management">'+html+'<p id="gate-error" class="error" role="alert"></p></div>');this.nav();},
