 async route(){const scope=location.pathname+location.search,product=ProductContext.code;try{const q=new URLSearchParams(location.search);if(!this.can('gate:read'))throw Error(this.t('无车辆出厂权限','No gate access permission'));if(q.get('view')==='printers')history.replaceState(history.state,'',this.path());q.has('permit')?await this.detail(q.get('permit')):await this.list();if(scope===location.pathname+location.search&&product===ProductContext.code)ProductContext.dirty=false;}catch(e){if(scope!==location.pathname+location.search||product!==ProductContext.code)return;this.page(this.t('车辆出厂管理','Vehicle Gate Exit'),'<p class="error" role="alert">'+esc(this.error(e))+'</p>');}},
