const gateShow=Router.performShow.bind(Router);Router.performShow=async function(){if(location.pathname==='/overview'&&new URLSearchParams(location.search).get('management')==='todos'&&GateUI.can('gate:exit')){const d=await API.request(GateUI.base()+'/tasks'),t=GateUI.t;GateUI.page(t('我的待办','My Tasks'),CobaltSalesUI.table([['出门证编号','Gate Permit No.'],['状态','State'],['操作','Actions']],d.items.map(r=>'<tr><td>'+esc(r.document_no)+'</td><td>'+GateUI.status(r.status)+'</td><td><a class="button secondary compact" href="'+esc(r.href)+'">'+t('办理车辆出厂','Process Gate Exit')+'</a></td></tr>'),'gate-todos'));for(const nav of document.querySelectorAll('.sidebar nav,.mobile-primary')){for(const a of nav.querySelectorAll('[data-primary-route]'))a.classList.toggle('nav-active',a.dataset.primaryRoute==='overview');}document.querySelector('.breadcrumb strong').textContent=t('我的待办','My Tasks');return;}if(!GateUI.active()){await gateShow();GateUI.nav();return;}this.current=location.pathname;this.rendering=true;try{await GateUI.route();}finally{this.rendering=false;}};
const gateNav=ProductPolish.nav.bind(ProductPolish);ProductPolish.nav=()=>{gateNav();GateUI.nav();};ShippingOverview.departures=()=>GateUI.route();
