ShippingOverview.loadingPlans=async function(){const t=GateUI.t,q=new URLSearchParams(location.search);if(!q.has('page_size'))q.set('page_size',25);const d=await API.request(CobaltLoadingUI.base+'/plans?'+q),columns=['invoice_no','packing_list_no','preparation_batch_no','customer_name','vehicle_no','contract_no','planned_load_date','status'],items=d.items.map(r=>({...r,status:CobaltLoadingUI.state(r.status),actions:[{label:t('查看详情','View Details'),href:r.historical_import?r.href:'/loading-plans/orders/'+r.id},...(r.status==='DRAFT'&&CobaltUI.can('loading-plan:write')?[{label:t('编辑','Edit'),href:'/loading-plans/'+r.id+'/edit'}]:[])]}));CobaltUI.page(t('装车计划管理','Arrival Register & Loading Plan'),`<div class="shipping-management"><div class="business-toolbar yard-tabs"><a class="button secondary" href="/loading-plans">${t('车辆到厂登记','Vehicle Arrivals')}</a><a class="button primary" href="/loading-plans/query">${t('装车计划查询','Loading Plan Query')}</a></div><form class="filters" id="v34-list-filter"><div class="form-grid"><label>${t('查询内容','Search')}<input name="search" maxlength="160" value="${esc(q.get('search')||'')}"></label><label>${t('状态','State')}<select name="status"><option value="">${t('全部状态','All States')}</option>${['DRAFT','MATCHED','OUTBOUND'].map(s=>'<option value="'+s+'" '+(q.get('status')===s?'selected':'')+'>'+CobaltLoadingUI.state(s)+'</option>').join('')}</select></label></div><div class="business-toolbar"><button class="button secondary">${t('查询','Search')}</button><a class="button secondary" href="/loading-plans/query">${t('重置筛选','Reset Filters')}</a></div></form>${Management.table(items,columns,true,{invoice_no:t('装车计划号/发票号','Loading Plan / Invoice No.'),vehicle_no:t('车牌号','Truck No.'),packing_list_no:t('装箱单号（Packing List No.）','Packing List No.'),preparation_batch_no:t('批次号','Lot Number')})}${Management.pager(d)}</div>`);$('v34-list-filter').onsubmit=e=>{e.preventDefault();Router.go('/loading-plans/query?'+new URLSearchParams(new FormData(e.target)));};Management.bindPaging(d,q=>Router.go('/loading-plans/query?'+q));LoadingFiltersR9.query($('v34-list-filter'),d,true);I18n.apply();ProductContext.dirty=false;};

const gateDetail=CobaltExecutionUI.detail.bind(CobaltExecutionUI);CobaltExecutionUI.detail=async function(id){await gateDetail(id);document.querySelector('.co-execution-page h2')?.insertAdjacentHTML('afterend','<p class="dialog-notice">'+GateUI.t('原版本离场节点保留为出库流程申报，不代表车辆实际通过厂区出口。完成最终出库审批后，由销售在车辆出厂管理中打印出门证并确认实际出厂。既有离场历史保留原始含义和时间。','The legacy departure node is retained as an stock issue workflow declaration. It does not establish physical gate exit. After final approval, Sales prints the permit and confirms physical exit in Vehicle Gate Exit. Existing departure history keeps its original meaning and time.')+'</p>');};

