const gateMount=ProductContext.mount.bind(ProductContext);ProductContext.mount=function(){gateMount();const set=I18n.set.bind(I18n);I18n.set=language=>{const onGate=GateUI.active(),scope=location.pathname+location.search,product=ProductContext.code,forms=onGate?[...document.querySelectorAll('#page-content form')].map(f=>({id:f.id,values:[...f.elements].filter(e=>e.name).map(e=>[e.name,e.type==='checkbox'?e.checked:e.value])})):[],dirty=ProductContext.dirty,global=ProductContext.globalPage.bind(ProductContext);let result;try{if(onGate)ProductContext.globalPage=p=>p===location.pathname||global(p);result=set(language);}finally{ProductContext.globalPage=global;}if(onGate){GateUI.preserveVersion=dirty?GateUI.detailVersion:null;}if(onGate){const preservedVersion=GateUI.preserveVersion;GateUI.route().then(()=>{if(scope===location.pathname+location.search&&product===ProductContext.code){for(const x of forms){const f=document.getElementById(x.id);if(f)for(const [k,v]of x.values){const e=f.elements[k];if(e)e.type==='checkbox'?e.checked=v:e.value=v;}}ProductContext.dirty=dirty;}if(GateUI.preserveVersion===preservedVersion)GateUI.preserveVersion=null;});}return result;};};

